// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    receive() external payable {}

    function testFuzz_property(uint64 t, uint64 d, address actor) public {
        // keep actor an EOA distinct from c and the test contract so transfers succeed
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(actor.code.length == 0);

        vm.warp(t);
        vm.roll(d);

        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        bool won = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2 == 0;
        assertTrue(won ? c.pot() == 0 : c.pot() == 10);
    }
}
